struct TranscodingVideoStream {
  VIDEO_SOURCE_TYPE sourceType;
  uid_t remoteUserUid;
  const char* imageUrl;
  int mediaPlayerId;
  int x;
  int y;
  int width;
  int height;
  int zOrder;
  double alpha;
  bool mirror;
};

public static class TranscodingVideoStream {
    public int remoteUserUid;
    public Constants.VideoSourceType sourceType;
    public String imageUrl;
    public int mediaPlayerId;
    public int x;
    public int y;
    public int width;
    public int height;
    public int zOrder;
    public double alpha;
    public boolean mirror;
  }

__attribute__((visibility("default"))) @interface AgoraTranscodingVideoStream: NSObject
@property (assign, nonatomic) AgoraVideoSourceType sourceType;
@property (assign, nonatomic) NSUInteger remoteUserUid;
@property (copy, nonatomic) NSString * _Nullable imageUrl;
@property(assign, nonatomic) NSUInteger mediaPlayerId;
@property (assign, nonatomic) CGRect rect;
@property (assign, nonatomic) NSInteger zOrder;
@property(assign, nonatomic) double alpha;
@property(assign, nonatomic) BOOL mirror;
@end

__attribute__((visibility("default"))) @interface AgoraTranscodingVideoStream: NSObject
@property (assign, nonatomic) NSUInteger remoteUserUid;
